def transform(grid):
    """Overlay the two aligned nonzero patterns across a solid separator; color overlaps 2."""
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        if row[0] != 0 and all(value == row[0] for value in row):
            top, bottom = grid[:r], grid[r + 1:]
            if top and len(top) == len(bottom):
                return [[2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                         for j in range(w)] for i in range(len(top))]
    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[i][c] == color for i in range(h)):
            left_width, right_width = c, w - c - 1
            if left_width and left_width == right_width:
                return [[2 if grid[i][j] != 0 and grid[i][c + 1 + j] != 0 else 0
                         for j in range(left_width)] for i in range(h)]
    raise ValueError("No aligned uniform separator found")

